package com.carlesso.goalfather.adapter.out.persistence.entity

import jakarta.persistence.Column
import jakarta.persistence.Entity
import jakarta.persistence.GeneratedValue
import jakarta.persistence.GenerationType
import jakarta.persistence.Id
import jakarta.persistence.Table

/**
 * Entidade JPA de usuário (issue #18). Separada do domínio [com.carlesso.goalfather.domain.model.User]
 * pela regra de ouro — nada de JPA no domínio.
 *
 * `id` é IDENTITY: gerado pelo banco no insert (a migração cria a coluna como
 * `GENERATED BY DEFAULT AS IDENTITY`). `username` é único (índice na migração).
 */
@Entity
@Table(name = "users")
class UserEntity(
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "id")
    var id: Long = 0,

    @Column(name = "username", nullable = false, unique = true)
    var username: String = "",

    @Column(name = "password_hash", nullable = false)
    var passwordHash: String = "",

    @Column(name = "club_id")
    var clubId: Long? = null,
)
